import{_ as a,o as t,c as o,a7 as r}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Personix Data Deletion","description":"Official data-deletion instructions for Personix.","frontmatter":{"title":"Personix Data Deletion","description":"Official data-deletion instructions for Personix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/personix.md","filePath":"data-deletion/personix.md"}'),s={name:"data-deletion/personix.md"};function i(n,e,l,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="delete-personix-data" tabindex="-1">Delete Personix Data <a class="header-anchor" href="#delete-personix-data" aria-label="Permalink to &quot;Delete Personix Data&quot;">​</a></h1><p>Personix has no online account or developer-operated cloud database. Its app data is stored on your device.</p><h2 id="delete-individual-records" tabindex="-1">Delete individual records <a class="header-anchor" href="#delete-individual-records" aria-label="Permalink to &quot;Delete individual records&quot;">​</a></h2><p>Delete saved content, family or health records, vehicles, notes, and checklists from their corresponding app screens.</p><h2 id="delete-all-personix-data" tabindex="-1">Delete all Personix data <a class="header-anchor" href="#delete-all-personix-data" aria-label="Permalink to &quot;Delete all Personix data&quot;">​</a></h2><p>Open <strong>Settings</strong>, choose <strong>Delete all data</strong>, review the warning, and confirm. If an app PIN is configured, authorize the action as requested. You can also clear Personix storage from Android system settings, clear browser site data, or uninstall the app.</p><h2 id="delete-exported-files" tabindex="-1">Delete exported files <a class="header-anchor" href="#delete-exported-files" aria-label="Permalink to &quot;Delete exported files&quot;">​</a></h2><p>Deleting app data does not remove <code>.pxbackup</code> files saved or shared outside the app. Delete those separately from every destination.</p><p>Because the developer does not hold Personix account data, emailing support cannot delete records stored only on your device.</p>',9)])])}const u=a(s,[["render",i]]);export{h as __pageData,u as default};
